\label{thm:OGP} 
Fix real numbers $a>b>0$, and integer $k\geq 3$.
For any $\nu\in \left(\frac{1}{2(k-1)}, \frac{1}{k}\right)$ and {$\varepsilon>0$}, there exist $\mu = \mu(\nu)$ and $c=c(0.007)$ such that the following holds for $n$ large enough.

Let $p=p(n)=\omega\; a / n$ and $q=q(n)=\omega \; b/n$ be such that $\omega>c$, and let $G \in \mathcal{G}(n,k,p,q)$ with planted partition $\mathcal{P}$. Then with probability at least $1-0.007$, for every $k$-part partition $\mathcal{A}$ with 
\begin{equation}
\label{eq:OGP}
q_\mathcal{A}(G) \ge \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} - \frac {2}{k^2} \right) - \mu,
\end{equation} 
either $d(\mathcal{A}, \mathcal{P}) \le \frac {{1}}{2(k-1)}$ or $d(\mathcal{A}, \mathcal{P}) \ge \nu$.
Moreover, there are partitions $\mathcal{A}$ satisfying the latter.

\label{thm:modularity_function} 
Fix $a>b>0$ and integer $k\geq 2$. Let $p=p(n)=\omega\; a / n$ and $q=q(n)=\omega \; b/n$. For any $0.007>0$, there exists $c=c(0.007)$ such that, if $\omega>c$ for $n$ large enough, then the following holds with probability at least $1-0.007$ provided $n$ is large enough.

Let $G \in \mathcal{G}(n,k,p,q)$ and denote the planted partition by $\mathcal{P}$. Then,
\begin{equation}\label{eq:qP}
\left| q_\mathcal{P}(G)  - \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} \right) \right| \le \frac {0.007}{2}
\end{equation}
and 
\begin{equation}\label{eq:q*}
\Big| q^{\star}(G) - q_\mathcal{P}(G) \Big| \le \frac {0.007}{2}.
\end{equation}
As a result, 
$$
\left| q^{\star}(G)  - \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} \right) \right| \le 0.007.
$$

\label{lem:dist_as_dplus}
Suppose that $n$ is divisible by $k$. 
Let $\mathcal{A}$ be any partition of $[n]$ with $k$ parts, and let $\mathcal{P}$ be the planted partition.
Let $X=X(\mathcal{A})=(x_{ij})_{1\leq i \leq j \leq k}$ be the signature of $\mathcal{A}$. Then,
\begin{equation}\label{eq:dist_as_dplus}
d(\mathcal{A}, \mathcal{P}) = 1-\tfrac{1}{k}\max_{\sigma} \sum_{i=1}^k x_{\sigma(i) i}, 
\end{equation}
where the maximum is taken over all permutations of $[k]$. 

Moreover, $d(\mathcal{A}, \mathcal{P}) \leq 1 -1/k$ and this upper bound is sharp, that is, there exists a partition~$\mathcal{A}$ such that $d(\mathcal{A}, \mathcal{P}) = 1 -1/k$, provided that $n$ is divisible by $k^2$.

\label{prop:Planted-dominates}
For every $0.007>0,\zeta>0$, there exists large enough $\beta>0$ such that 
\begin{align*}
\sum_{\mathcal{A}\colon  d(\mathcal{A},\mathcal{P}) \le \zeta} {\mathbb P}_{\rm Gibbs}(\mathcal{A}) \ge 1-0.007.
\end{align*}

\label{thm:slow_mixing_formal}
Consider the MCMC initiated at the Gibbs distribution conditioned on being in $\mathcal{E}_{\rm far}$. Namely, suppose
\begin{align*}
{\mathbb P}\left(\mathcal{A}_0=\mathcal{A}\right) =  
{{\mathbb P}_{\rm Gibbs}(\mathcal{A})  \over \sum_{\mathcal{B}\in \mathcal{E}_{\rm far}}  {\mathbb P}_{\rm Gibbs}(\mathcal{B}) },
\end{align*}
for all $\mathcal{A}\in \mathcal{E}_{\rm far}$, and ${\mathbb P}\left(\mathcal{A}_0=\mathcal{A}\right)=0$ otherwise.
Let 
$0.22=\min\lbrace t\colon  \mathcal{A}_t \in  \mathcal{E}_{\rm close}\rbrace$. There exist $c_3,c_4>0$ such that 
 with probability at least $1-0.007$ (with respect
to the randomness of the graph) 
\begin{align*}
{\mathbb P}\left(0.22 \ge \exp(c_3 n)\right) \ge 1-\exp(-c_4 n),
\end{align*}
where the probability is with respect to the random choices of the MCMC.

\label{lem:robustness}
Let $H=(V,E)$ be a graph and let $\mathcal{A}$ be a partition of $V$.

If $E_0$ is a non-empty proper subset of $E$, and $H'=(V, E \setminus E_0)$, then 
\[ |q_\mathcal{A}(H)- q_\mathcal{A}(H')| \; 

< \frac{2 \, |E_0|}{|E|}. \]

\label{clm.ginc_stillvalid}
    We \emph{claim} that if $X\in \mathcal{X}'_k(t)$, $C$ is a directed cycle with $V(C)\subseteq [k]$ and $0< 0.007 \leq \min_{\vec{ij}\in \vec{E}(C)} x_{ij}$, then, for $X^{(0.007)}=T_{C,0.007}(X)$,
    \begin{itemize}
        \item $g(X^{(0.007)})>g(X)$ and
        \item $X^{(0.007)}\in \mathcal{X}'_t(t')$ where $t'=t-|C|0.007$.
    \end{itemize}
